INSERT INTO "Destination" (city, country, image, description, rating, duration, price, category) VALUES
('Buenos Aires', 'Argentina', 'https://images.unsplash.com/photo-1589080598137-2e7c5beefa1e?w=800&q=80', 'Tango, steakhouses, and Paris of South America.', 4.8, '6-9 days', 'From $899', 'City'),
('Patagonia', 'Argentina', 'https://images.unsplash.com/photo-1501854140801-50d01698950b?w=800&q=80', 'Glaciers, condors, and end-of-the-world trekking.', 5.0, '10-14 days', 'From $2,199', 'Adventure'),
('Rio de Janeiro', 'Brazil', 'https://images.unsplash.com/photo-1483729558449-99ef09a8c325?w=800&q=80', 'Christ the Redeemer, Copacabana, and carnival fever.', 4.8, '6-9 days', 'From $999', 'Beach'),
('Sao Paulo', 'Brazil', 'https://images.unsplash.com/photo-1578002171197-2d4e7e4b82c1?w=800&q=80', 'Art, gastronomy, and the business heart of Latin America.', 4.6, '4-7 days', 'From $899', 'City'),
('Amazon', 'Brazil', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 'Jungle lodges, pink dolphins, and canopy adventures.', 4.9, '7-10 days', 'From $1,599', 'Nature'),
('Machu Picchu', 'Peru', 'https://images.unsplash.com/photo-1526392060635-9d6019884377?w=800&q=80', 'Incan citadel above the clouds, Cusco, and Sacred Valley.', 5.0, '8-12 days', 'From $1,499', 'Culture'),
('Lima', 'Peru', 'https://images.unsplash.com/photo-1531968455001-5c5272a41129?w=800&q=80', 'Best food city in South America, ceviche and Miraflores.', 4.8, '4-6 days', 'From $799', 'City'),
('Cartagena', 'Colombia', 'https://images.unsplash.com/photo-1583001931096-959e9a1a6223?w=800&q=80', 'Colorful colonial walls, Caribbean coast, and salsa nights.', 4.9, '5-7 days', 'From $849', 'Beach'),
('Medellin', 'Colombia', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'City of eternal spring, cable cars, and Pablo''s ghost.', 4.8, '5-7 days', 'From $799', 'City'),
('Bogota', 'Colombia', 'https://images.unsplash.com/photo-1541426680606-b87c09f82e01?w=800&q=80', 'Gold Museum, street art, and Monserrate mountain.', 4.7, '4-6 days', 'From $749', 'City'),
('Galapagos', 'Ecuador', 'https://images.unsplash.com/photo-1548199569-3e1c6aa8f469?w=800&q=80', 'Darwin wildlife, blue-footed boobies, and volcanic islands.', 5.0, '7-10 days', 'From $2,999', 'Nature'),
('Quito', 'Ecuador', 'https://images.unsplash.com/photo-1531256456869-ce942a665e80?w=800&q=80', 'Middle of the world, colonial old town, and Cotopaxi.', 4.7, '4-6 days', 'From $749', 'Culture'),
('Santiago', 'Chile', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Atacama gateway, Andes views, and wine valleys.', 4.7, '5-8 days', 'From $899', 'City'),
('Atacama', 'Chile', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=800&q=80', 'Driest desert, stargazing paradise, and salt flats.', 5.0, '5-7 days', 'From $1,299', 'Nature'),
('La Paz', 'Bolivia', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Highest capital city, Salar de Uyuni, and death road.', 4.7, '6-9 days', 'From $799', 'Adventure'),
('Montevideo', 'Uruguay', 'https://images.unsplash.com/photo-1580060839134-75a5edca2e99?w=800&q=80', 'Rambla promenade, candombe drums, and asado culture.', 4.7, '4-6 days', 'From $849', 'City'),
('Asuncion', 'Paraguay', 'https://images.unsplash.com/photo-1569591559621-921d4b7ef74b?w=800&q=80', 'Guarani culture, colonial churches, and Jesuit missions.', 4.4, '3-5 days', 'From $649', 'Culture'),
('Caracas', 'Venezuela', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'Angel Falls, tepuis, and Venezuelan coast.', 4.3, '5-8 days', 'From $799', 'Nature'),
('Georgetown', 'Guyana', 'https://images.unsplash.com/photo-1516026672322-bc52d61a55d5?w=800&q=80', 'Kaieteur Falls, rainforest lodges, and Iwokrama.', 4.6, '7-10 days', 'From $1,099', 'Nature'),
('Paramaribo', 'Suriname', 'https://images.unsplash.com/photo-1527631746610-bca00a040d60?w=800&q=80', 'Dutch colonial UNESCO town and Amazon river tribes.', 4.5, '5-7 days', 'From $899', 'Culture');
